import{_ as a,o as r,c as i,a2 as s}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"ADR-001: DOM/SVG in headless Chromium as the rendering surface","description":"","frontmatter":{},"headers":[],"relativePath":"adr/001-dom-svg-rendering-surface.md","filePath":"adr/001-dom-svg-rendering-surface.md"}'),n={name:"adr/001-dom-svg-rendering-surface.md"};function t(o,e,d,c,l,h){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-001-dom-svg-in-headless-chromium-as-the-rendering-surface" tabindex="-1">ADR-001: DOM/SVG in headless Chromium as the rendering surface <a class="header-anchor" href="#adr-001-dom-svg-in-headless-chromium-as-the-rendering-surface" aria-label="Permalink to &quot;ADR-001: DOM/SVG in headless Chromium as the rendering surface&quot;">​</a></h1><ul><li>Status: accepted · Date: 2026-10-15</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Episodes need rich typography (Arabic shaping, bidi, variable fonts), crisp vector diagrams and code with syntax colors. Options considered: HTML Canvas 2D, Motion Canvas, Remotion, and plain DOM/SVG rendered by headless Chromium.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Components render to DOM and SVG inside a 1080×1920 page. Chromium (pinned through Playwright) captures each frame. Canvas is used only where per-pixel work is natural (grain, particles, background glow).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Text layout, Arabic shaping and bidi come from Chromium, the most battle-tested engine for them.</li><li>The same runtime powers the studio preview and the final render (what you see is what you get).</li><li>Remotion was rejected: its license is not permissive for companies, and it brings React. Motion Canvas was rejected: its own text layout lacks robust Arabic/bidi support.</li><li>Frame capture costs ~100 ms/frame, which parallel workers absorb (ADR-005).</li></ul>',8)])])}const p=a(n,[["render",t]]);export{m as __pageData,p as default};
